-- =====================================================================
--  PORTAL DE CONSULTA DE CREDITOS DE MOTOS (RENTAR) - PROTOTIPO
--  Script 02: DATOS FICTICIOS para pruebas y demostracion
--
--  AVISO: todos los CLIENTES, documentos, placas, telefonos, correos y
--  valores de creditos de este archivo son INVENTADOS. No corresponden a
--  clientes reales. Los CANALES DE CONTACTO si son los de atencion de
--  Rentar Inversiones Ltda. (WhatsApp, correo, oficina en Neiva).
--
--  Motos Yamaha: precio de lista + matricula con reserva (prenda) tomados
--  de la lista de precios del prototipo. Tasas de Rentar: 2,84 % mensual general
--  y 1,80 % para empleados de Rentar Inversiones o de Yamaha (caso especial).
--
--  TIEMPO REAL: todas las fechas se calculan con respecto al DIA EN QUE SE
--  EJECUTA este script (CURDATE()). Las cuotas vencen en las fechas de corte
--  de la entidad: el dia 5 o el dia 20 de cada mes. Asi, sin importar cuando
--  se cargue, Laura queda al dia, Andres con 3 cuotas vencidas, Diana con el
--  credito cancelado, etc., y la mora/dias se siguen moviendo cada dia.
--  Las tablas de cuotas se calcularon con el sistema frances (cuota fija),
--  redondeando a pesos; la ultima cuota ajusta la diferencia de redondeo.
--
--  Credenciales de prueba:
--    Administrador:  usuario admin           clave Admin2026*
--    Clientes:       usuario = su documento  clave Cliente2026*
--
--  Requiere haber ejecutado antes 01_esquema.sql.
--  Uso (CMD, en C:\proyectos\portal-creditos):
--    mysql -u portal_user -p portal_creditos < database\02_datos_ficticios.sql
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE mensaje_cliente;
TRUNCATE TABLE auditoria;
TRUNCATE TABLE importacion_error;
TRUNCATE TABLE importacion;
TRUNCATE TABLE canal_contacto;
TRUNCATE TABLE solicitud_levantamiento;
TRUNCATE TABLE requisito_levantamiento;
TRUNCATE TABLE paz_y_salvo;
TRUNCATE TABLE aplicacion_pago;
TRUNCATE TABLE pago;
TRUNCATE TABLE cuota;
TRUNCATE TABLE credito;
TRUNCATE TABLE vehiculo;
TRUNCATE TABLE usuario;
TRUNCATE TABLE cliente;
SET FOREIGN_KEY_CHECKS = 1;

-- Fechas ancla (dias de corte 5 y 20)
SET @hoy = CURDATE();
SET @u5  = IF(DAY(@hoy) >= 5,  DATE(DATE_FORMAT(@hoy, '%Y-%m-05')), DATE(DATE_FORMAT(@hoy - INTERVAL 1 MONTH, '%Y-%m-05')));
SET @v5  = IF(DAY(@hoy) > 5,   DATE(DATE_FORMAT(@hoy, '%Y-%m-05')), DATE(DATE_FORMAT(@hoy - INTERVAL 1 MONTH, '%Y-%m-05')));
SET @u20 = IF(DAY(@hoy) >= 20, DATE(DATE_FORMAT(@hoy, '%Y-%m-20')), DATE(DATE_FORMAT(@hoy - INTERVAL 1 MONTH, '%Y-%m-20')));
SET @p20 = IF(DAY(@hoy) < 20,  DATE(DATE_FORMAT(@hoy, '%Y-%m-20')), DATE(DATE_FORMAT(@hoy + INTERVAL 1 MONTH, '%Y-%m-20')));

START TRANSACTION;

