COMMIT;

-- ---------------------------------------------------------------------
-- VERIFICACION: resumen de cada credito (cuotas pagadas y vencidas a hoy)
-- ---------------------------------------------------------------------
SELECT c.numero_credito,
       CONCAT(cl.nombres, ' ', cl.apellidos) AS cliente,
       c.estado,
       c.estado_prenda,
       c.saldo_capital,
       SUM(cu.estado = 'PAGADA') AS cuotas_pagadas,
       SUM(cu.estado <> 'PAGADA' AND cu.fecha_vencimiento < CURDATE()) AS cuotas_vencidas,
       c.plazo_meses
FROM credito c
JOIN cliente cl ON cl.id = c.cliente_id
JOIN cuota cu ON cu.credito_id = c.id
GROUP BY c.id
ORDER BY c.id;
